// Spring Boot - Response Time Optimization Techniques

// 1. DATABASE QUERY OPTIMIZATION
// ================================

// BAD: N+1 Query Problem
@GetMapping("/users")
public List<UserDTO> getUsers() {
    List<User> users = userRepository.findAll();
    // Each user.getOrders() triggers separate query!
    return users.stream()
        .map(user -> new UserDTO(user, user.getOrders()))
        .collect(Collectors.toList());
}

// GOOD: Use JOIN FETCH to load in single query
@Repository
public interface UserRepository extends JpaRepository<User, Long> {
    @Query("SELECT u FROM User u LEFT JOIN FETCH u.orders")
    List<User> findAllWithOrders();
}

@GetMapping("/users")
public List<UserDTO> getUsers() {
    // Single query with JOIN
    List<User> users = userRepository.findAllWithOrders();
    return users.stream()
        .map(user -> new UserDTO(user, user.getOrders()))
        .collect(Collectors.toList());
}

// 2. CACHING WITH SPRING CACHE
// =============================

import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.annotation.EnableCaching;

@Configuration
@EnableCaching
public class CacheConfig {

    @Bean
    public CacheManager cacheManager() {
        // Use Redis for distributed cache
        return RedisCacheManager.builder(redisConnectionFactory())
            .cacheDefaults(RedisCacheConfiguration.defaultCacheConfig()
                .entryTtl(Duration.ofMinutes(10)))
            .build();
    }
}

@Service
public class UserService {

    @Cacheable(value = "users", key = "#id")
    public User getUserById(Long id) {
        // This will be cached - subsequent calls return cached value
        return userRepository.findById(id).orElseThrow();
    }

    @CacheEvict(value = "users", key = "#user.id")
    public User updateUser(User user) {
        // This evicts cache entry when user updated
        return userRepository.save(user);
    }
}

// 3. ASYNC PROCESSING
// ===================

import org.springframework.scheduling.annotation.Async;
import org.springframework.scheduling.annotation.EnableAsync;

@Configuration
@EnableAsync
public class AsyncConfig {

    @Bean
    public Executor taskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(20);
        executor.setQueueCapacity(100);
        executor.setThreadNamePrefix("async-");
        executor.initialize();
        return executor;
    }
}

@Service
public class EmailService {

    @Async
    public CompletableFuture<Void> sendEmailAsync(String to, String subject, String body) {
        // This runs in background thread - doesn't block request
        emailClient.send(to, subject, body);
        return CompletableFuture.completedFuture(null);
    }
}

@RestController
public class OrderController {

    @PostMapping("/orders")
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        Order order = orderService.createOrder(request);

        // Send confirmation email asynchronously - don't wait
        emailService.sendEmailAsync(order.getEmail(), "Order Confirmed", "...");

        // Return immediately without waiting for email
        return ResponseEntity.ok(order);
    }
}

