// 6. EXTERNAL API CALLS WITH TIMEOUT
// ===================================

import org.springframework.web.reactive.function.client.WebClient;

@Service
public class ExternalApiService {

    private final WebClient webClient;

    public ExternalApiService(WebClient.Builder webClientBuilder) {
        this.webClient = webClientBuilder
            .baseUrl("https://api.external.com")
            .build();
    }

    public Data fetchData(String id) {
        return webClient.get()
            .uri("/data/{id}", id)
            .retrieve()
            .bodyToMono(Data.class)
            .timeout(Duration.ofSeconds(5))  // Timeout after 5 seconds
            .block();
    }

    // Better: Async with fallback
    public Mono<Data> fetchDataAsync(String id) {
        return webClient.get()
            .uri("/data/{id}", id)
            .retrieve()
            .bodyToMono(Data.class)
            .timeout(Duration.ofSeconds(5))
            .onErrorResume(e -> {
                // Fallback on error/timeout
                return Mono.just(Data.defaultData());
            });
    }
}

