// JUnit Performance Testing
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.http.ResponseEntity;
import java.time.Duration;
import java.time.Instant;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
public class ResponseTimeTest {

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    public void apiResponseShouldBeFast() {
        Instant start = Instant.now();

        ResponseEntity<String> response = restTemplate
            .getForEntity("/api/users", String.class);

        Duration duration = Duration.between(start, Instant.now());

        assertEquals(200, response.getStatusCodeValue());
        assertTrue(duration.toMillis() < 600, 
            "API response took " + duration.toMillis() + "ms (expected < 600ms)");
    }

    @Test
    public void databaseQueriesShouldBeOptimized() {
        // Enable query logging to detect N+1
        Instant start = Instant.now();

        List<User> users = userService.getAllUsers();

        Duration duration = Duration.between(start, Instant.now());

        assertFalse(users.isEmpty());
        // Should complete in < 100ms with proper joins
        assertTrue(duration.toMillis() < 100,
            "Database query took " + duration.toMillis() + "ms (expected < 100ms)");
    }

    @Test
    public void cachesShouldReduceResponseTime() {
        // First call - cache miss
        Instant start1 = Instant.now();
        User user1 = userService.getUserById(1L);
        Duration duration1 = Duration.between(start1, Instant.now());

        // Second call - cache hit
        Instant start2 = Instant.now();
        User user2 = userService.getUserById(1L);
        Duration duration2 = Duration.between(start2, Instant.now());

        assertEquals(user1.getId(), user2.getId());
        // Cached call should be much faster
        assertTrue(duration2.toMillis() < duration1.toMillis() / 10,
            "Cached response not faster: " + duration2.toMillis() + "ms vs " + duration1.toMillis() + "ms");
    }
}

