// Express.js - Response Time Optimization

const express = require('express');
const redis = require('redis');
const { promisify } = require('util');
const app = express();

// 1. REDIS CACHING
// ================

const redisClient = redis.createClient({
  host: 'localhost',
  port: 6379
});

const getAsync = promisify(redisClient.get).bind(redisClient);
const setAsync = promisify(redisClient.set).bind(redisClient);

// Cache middleware
const cache = (duration) => async (req, res, next) => {
  const key = `cache:${req.originalUrl}`;

  try {
    const cached = await getAsync(key);
    if (cached) {
      // Cache hit - return immediately
      return res.json(JSON.parse(cached));
    }

    // Cache miss - continue to handler
    res.sendResponse = res.json;
    res.json = async (body) => {
      // Cache the response
      await setAsync(key, JSON.stringify(body), 'EX', duration);
      res.sendResponse(body);
    };
    next();
  } catch (err) {
    next();
  }
};

// Use caching middleware
app.get('/api/users', cache(300), async (req, res) => {
  // This will be cached for 5 minutes
  const users = await db.query('SELECT * FROM users');
  res.json(users);
});

// 2. DATABASE CONNECTION POOLING
// ===============================

const { Pool } = require('pg');

const pool = new Pool({
  host: 'localhost',
  database: 'mydb',
  user: 'user',
  password: 'pass',
  max: 20,              // Max connections
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000
});

// Good: Use pool for queries
app.get('/api/users/:id', async (req, res) => {
  const client = await pool.connect();
  try {
    const result = await client.query(
      'SELECT * FROM users WHERE id = $1',
      [req.params.id]
    );
    res.json(result.rows[0]);
  } finally {
    client.release();
  }
});

// 3. ASYNC/AWAIT FOR NON-BLOCKING I/O
// ====================================

const axios = require('axios');

// BAD: Synchronous/blocking
app.get('/api/data', (req, res) => {
  // Multiple sequential API calls - slow!
  const user = fetchUser(req.userId);
  const orders = fetchOrders(user.id);
  const products = fetchProducts(orders);
  res.json({ user, orders, products });
});

// GOOD: Parallel async calls
app.get('/api/data', async (req, res) => {
  try {
    // Fetch in parallel - much faster!
    const [user, orders, products] = await Promise.all([
      fetchUser(req.userId),
      fetchOrders(req.userId),
      fetchProducts(req.userId)
    ]);
    res.json({ user, orders, products });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 4. EXTERNAL API TIMEOUTS
// ========================

const axiosWithTimeout = axios.create({
  timeout: 5000,  // 5 second timeout
  headers: { 'Content-Type': 'application/json' }
});

async function fetchExternalData(id) {
  try {
    const response = await axiosWithTimeout.get(
      `https://api.external.com/data/${id}`
    );
    return response.data;
  } catch (err) {
    if (err.code === 'ECONNABORTED') {
      console.error('Request timeout');
      return { error: 'Service unavailable' };
    }
    throw err;
  }
}

// 5. PAGINATION
// =============

app.get('/api/products', async (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 20;
  const offset = (page - 1) * limit;

  // Don't load all products - use LIMIT/OFFSET
  const result = await pool.query(
    'SELECT * FROM products ORDER BY name LIMIT $1 OFFSET $2',
    [limit, offset]
  );

  const countResult = await pool.query('SELECT COUNT(*) FROM products');
  const total = parseInt(countResult.rows[0].count);

  res.json({
    data: result.rows,
    pagination: {
      page,
      limit,
      total,
      pages: Math.ceil(total / limit)
    }
  });
});

// 6. BACKGROUND JOBS (Bull Queue)
// ================================

const Queue = require('bull');
const emailQueue = new Queue('email', {
  redis: { host: 'localhost', port: 6379 }
});

// Process jobs in background
emailQueue.process(async (job) => {
  await sendEmail(job.data.to, job.data.subject, job.data.body);
});

app.post('/api/orders', async (req, res) => {
  const order = await createOrder(req.body);

  // Queue email - don't wait for it
  await emailQueue.add({
    to: order.email,
    subject: 'Order Confirmed',
    body: `Order ${order.id} confirmed`
  });

  // Return immediately
  res.json(order);
});

// 7. RESPONSE TIME MONITORING
// ===========================

const responseTime = require('response-time');

// Log slow requests
app.use(responseTime((req, res, time) => {
  if (time > 1000) {
    console.warn(`Slow request: ${req.method} ${req.url} took ${time}ms`);
  }
}));

// 8. QUERY OPTIMIZATION
// =====================

// BAD: N+1 query
app.get('/api/users-with-orders', async (req, res) => {
  const users = await pool.query('SELECT * FROM users');

  for (let user of users.rows) {
    // Separate query for each user - N+1 problem!
    const orders = await pool.query(
      'SELECT * FROM orders WHERE user_id = $1',
      [user.id]
    );
    user.orders = orders.rows;
  }

  res.json(users.rows);
});

// GOOD: Single query with JOIN
app.get('/api/users-with-orders', async (req, res) => {
  const result = await pool.query(`
    SELECT 
      u.*,
      json_agg(o.*) as orders
    FROM users u
    LEFT JOIN orders o ON u.id = o.user_id
    GROUP BY u.id
  `);

  res.json(result.rows);
});

app.listen(3000);

