const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('Response Time Tests', () => {

  it('API should respond within 600ms', (done) => {
    const start = Date.now();

    request(app)
      .get('/api/users')
      .expect(200)
      .end((err, res) => {
        const duration = Date.now() - start;

        expect(duration).to.be.below(600,
          `Response took ${duration}ms (expected < 600ms)`);
        done(err);
      });
  });

  it('cached responses should be faster', (done) => {
    let firstDuration, secondDuration;

    // First request - cache miss
    const start1 = Date.now();
    request(app)
      .get('/api/products')
      .expect(200)
      .end(() => {
        firstDuration = Date.now() - start1;

        // Second request - cache hit
        const start2 = Date.now();
        request(app)
          .get('/api/products')
          .expect(200)
          .end(() => {
            secondDuration = Date.now() - start2;

            expect(secondDuration).to.be.below(firstDuration / 5,
              `Cached: ${secondDuration}ms, Original: ${firstDuration}ms`);
            done();
          });
      });
  });
});

